<?php
namespace App\Services\Finance;
use App\Models\WorkspaceMember;use App\Services\Access\WorkScopeService;
/** Provides finance access service behavior within the WorkIntel application. */ class FinanceAccessService{/** Initializes the class with its required dependencies and state. */ public function __construct(private readonly WorkScopeService $workScope){}/** Handles the expense member ids operation for the current WorkIntel workflow. */ public function expenseMemberIds(WorkspaceMember $actor):array{if($actor->hasPermission('expenses.manage'))return WorkspaceMember::where('workspace_id',$actor->workspace_id)->pluck('id')->map(fn($id)=>(int)$id)->all();if($actor->hasPermission('expenses.view_team'))return $this->workScope->teamMemberIds($actor);return[(int)$actor->id];}/** Determines whether the can view expense member condition is satisfied. */ public function canViewExpenseMember(WorkspaceMember $actor,int $memberId):bool{return in_array($memberId,$this->expenseMemberIds($actor),true);}/** Handles the assert can view expense member operation for the current WorkIntel workflow. */ public function assertCanViewExpenseMember(WorkspaceMember $actor,int $memberId):void{abort_unless($this->canViewExpenseMember($actor,$memberId),403,'This expense is outside your scope.');}}
